import java.util.List;

public class ListMath {
    public static int sum(List<Integer> nums) {
        if (nums == null) {
            return 0;
        }
        int total = 0;
        for (Integer n : nums) {
            if (n != null) {
                total += n;
            }
        }
        return total;
    }
}

test:
public class Test {
    public static void main(String[] a) {
        if (!(ListMath.sum(java.util.Arrays.asList(1, null, 2, null)) == 3)) throw new AssertionError("null elements");
        if (!(ListMath.sum(null) == 0)) throw new AssertionError("null list");
        if (!(ListMath.sum(java.util.List.of(4, 5)) == 9)) throw new AssertionError("normal");
        System.out.println("PASS");
    }
}
